import React from "react";
import { createRoot, type Root } from "react-dom/client";

export const consoleEntryName = "Open Agent Cluster Console";

export function ConsoleBootstrap() {
  return (
    <main aria-label={consoleEntryName}>
      <h1>{consoleEntryName}</h1>
      <p>Sign in to continue to your authorized workspace.</p>
    </main>
  );
}

export function mountConsoleBootstrap(mountElement: HTMLElement | null): Root {
  if (mountElement === null) {
    throw new Error("Console bootstrap requires a mount element.");
  }

  const root = createRoot(mountElement);
  root.render(<ConsoleBootstrap />);
  return root;
}
import { act } from "react";
import { render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { ConsoleBootstrap, mountConsoleBootstrap } from "./ConsoleBootstrap";

describe("ConsoleBootstrap", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("gives an anonymous visitor a named Console entry without a platform request", () => {
    const request = vi.fn();
    vi.stubGlobal("fetch", request);

    render(<ConsoleBootstrap />);

    expect(screen.getByRole("main", { name: "Open Agent Cluster Console" })).toBeVisible();
    expect(screen.getByRole("heading", { name: "Open Agent Cluster Console" })).toBeVisible();
    expect(screen.getByText("Sign in to continue to your authorized workspace.")).toBeVisible();
    expect(request).not.toHaveBeenCalled();
  });

  it("fails clearly when the Console mount point is unavailable", () => {
    expect(() => mountConsoleBootstrap(null)).toThrow("Console bootstrap requires a mount element.");
  });

  it("mounts the Console entry into its supplied root", async () => {
    const mountElement = document.createElement("div");
    let root: ReturnType<typeof mountConsoleBootstrap>;

    await act(async () => {
      root = mountConsoleBootstrap(mountElement);
    });

    expect(mountElement.querySelector("h1")).toHaveTextContent("Open Agent Cluster Console");

    await act(async () => root.unmount());
  });
});
